insert into public.challenges (slug, title, category, level, days, icon, next_start, proof, price_uzs, content) values
  ('cold-shower', '30 дней холодного душа', 'habits', 'medium', 30, 'snowflake', null, 'none', 0, '{"ru":{"title":"30 дней холодного душа","short":"Каждое утро заканчивайте душ холодной водой. Начинаем с 30 секунд.","goal":"Выработать устойчивую утреннюю привычку и натренировать реакцию на стресс. К финишу — 3 минуты холодной воды без подготовки.","rules":["Чекин до 12:00 по местному времени","Время под холодной водой растет каждую неделю","Пропуск одного дня допустим, двух подряд — серия сгорает","Отчет: короткая заметка о самочувствии"],"phases":[{"title":"Адаптация","tasks":["30 секунд холодной воды в конце душа","Дышите медленно: вдох на 4 счета, выдох на 6","45 секунд, начиная с ног"]},{"title":"Привыкание","tasks":["1 минута холодной воды","1 минута 15 секунд, без задержки дыхания","Запишите, как изменилась бодрость к обеду"]},{"title":"Устойчивость","tasks":["2 минуты холодной воды","Начните душ сразу с холодной воды","2 минуты 30 секунд"]},{"title":"Финиш","tasks":["3 минуты холодной воды","3 минуты и запись итогов недели"]}]},"uz":{"title":"30 kunlik sovuq dush","short":"Har tong dushni sovuq suv bilan yakunlang. 30 soniyadan boshlaymiz.","goal":"Barqaror ertalabki odat hosil qilish va stressga bardoshni chiniqtirish. Marraga kelib — tayyorgarliksiz 3 daqiqa sovuq suv.","rules":["Belgi mahalliy vaqt bilan soat 12:00 gacha qoʻyiladi","Sovuq suv ostidagi vaqt har hafta oshib boradi","Bir kun oʻtkazib yuborish mumkin, ketma-ket ikki kun — seriya uziladi","Hisobot: oʻzingizni qanday his qilayotganingiz haqida qisqa qayd"],"phases":[{"title":"Moslashuv","tasks":["Dush oxirida 30 soniya sovuq suv","Sekin nafas oling: 4 sanoqda nafas oling, 6 sanoqda chiqaring","45 soniya, oyoqlardan boshlab"]},{"title":"Koʻnikish","tasks":["1 daqiqa sovuq suv","1 daqiqa 15 soniya, nafasni ushlamasdan","Tushlikkacha tetiklik qanday oʻzgarganini yozib qoʻying"]},{"title":"Barqarorlik","tasks":["2 daqiqa sovuq suv","Dushni darhol sovuq suvdan boshlang","2 daqiqa 30 soniya"]},{"title":"Marra","tasks":["3 daqiqa sovuq suv","3 daqiqa va hafta yakunlarini yozib qoʻyish"]}]},"en":{"title":"30 Days of Cold Showers","short":"Finish every morning shower with cold water. We start with 30 seconds.","goal":"Build a lasting morning habit and train your stress response. By the finish: 3 minutes of cold water with no warm-up.","rules":["Check in before 12:00 local time","Time under cold water goes up every week","Missing one day is fine; miss two in a row and your streak resets","Report: a short note on how you feel"],"phases":[{"title":"Adaptation","tasks":["30 seconds of cold water at the end of your shower","Breathe slowly: in for 4 counts, out for 6","45 seconds, starting with your legs"]},{"title":"Getting used to it","tasks":["1 minute of cold water","1 minute 15 seconds, without holding your breath","Note how your energy by lunchtime has changed"]},{"title":"Resilience","tasks":["2 minutes of cold water","Start your shower with cold water right away","2 minutes 30 seconds"]},{"title":"Finish","tasks":["3 minutes of cold water","3 minutes and a write-up of the week"]}]}}'::jsonb),
  ('run-100', '100 км за месяц', 'sport', 'hard', 30, 'footprints', '2026-10-12'::date, 'required', 0, '{"ru":{"title":"100 км за месяц","short":"Накопительный бег: в сумме 100 километров за 30 дней в любом темпе.","goal":"Пробежать 100 км за календарный месяц, выстроив режим из 4–5 пробежек в неделю без травм.","rules":["Засчитываются пробежки с трека (GPS-приложение)","Минимальная дистанция одной пробежки — 2 км","Не более 15 км за день","Один день отдыха после каждых трех пробежек"],"phases":[{"title":"Втягивание","tasks":["Легкая пробежка 3 км","Отдых и растяжка 15 минут","Пробежка 4 км в разговорном темпе"]},{"title":"Объем","tasks":["Пробежка 5 км","Интервалы: 6 × 400 м","Отдых","Длительная 7 км"]},{"title":"Пик","tasks":["Пробежка 5 км","Темповая 4 км","Длительная 10 км","Отдых"]},{"title":"Добор","tasks":["Пробежка до цели по остатку","Восстановительная 3 км","Финальная пробежка"]}]},"uz":{"title":"Bir oyda 100 km","short":"Jamlanma yugurish: 30 kunda istalgan surʼatda jami 100 kilometr.","goal":"Kalendar oyi davomida 100 km yugurish va jarohatsiz haftasiga 4–5 ta yugurish tartibini yoʻlga qoʻyish.","rules":["Trek yozilgan yugurishlar hisoblanadi (GPS ilova)","Bitta yugurishning eng kam masofasi — 2 km","Kuniga 15 km dan oshmasin","Har uchta yugurishdan keyin bir kun dam olish"],"phases":[{"title":"Kirishish","tasks":["Yengil yugurish, 3 km","Dam olish va 15 daqiqa choʻzilish","Suhbat surʼatida 4 km yugurish"]},{"title":"Hajm","tasks":["5 km yugurish","Intervallar: 6 × 400 m","Dam olish","Uzoq masofa, 7 km"]},{"title":"Choʻqqi","tasks":["5 km yugurish","Temp yugurish, 4 km","Uzoq masofa, 10 km","Dam olish"]},{"title":"Yakunlash","tasks":["Maqsadgacha qolgan masofani yugurish","Tiklanish yugurishi, 3 km","Yakuniy yugurish"]}]},"en":{"title":"100 km in a Month","short":"Cumulative running: 100 kilometres total in 30 days, at any pace.","goal":"Run 100 km in a calendar month while building an injury-free routine of 4–5 runs a week.","rules":["Only runs with a recorded track count (GPS app)","Minimum distance per run: 2 km","No more than 15 km per day","One rest day after every three runs"],"phases":[{"title":"Easing in","tasks":["Easy 3 km run","Rest and 15 minutes of stretching","4 km run at a conversational pace"]},{"title":"Volume","tasks":["5 km run","Intervals: 6 × 400 m","Rest","Long run, 7 km"]},{"title":"Peak","tasks":["5 km run","Tempo run, 4 km","Long run, 10 km","Rest"]},{"title":"Closing the gap","tasks":["Run whatever is left to reach the goal","Recovery run, 3 km","Final run"]}]}}'::jsonb),
  ('deep-work', '21 день глубокой работы', 'growth', 'medium', 21, 'brain', null, 'none', 0, '{"ru":{"title":"21 день глубокой работы","short":"Ежедневные блоки работы без уведомлений: от 60 до 180 минут.","goal":"Научиться удерживать фокус на одной задаче и закрывать важные дела до обеда.","rules":["Телефон в другой комнате на время блока","Одна задача на блок, заранее записанная","Чекин: что сделано за блок, 1–2 предложения"],"phases":[{"title":"Разгон","tasks":["Блок 60 минут","Блок 60 минут + план на завтра","Блок 75 минут"]},{"title":"Нормализация","tasks":["Блок 90 минут","Два блока по 60 минут","Блок 90 минут без почты до полудня"]},{"title":"Глубина","tasks":["Блок 120 минут","Блок 150 минут","Блок 180 минут и ретро"]}]},"uz":{"title":"21 kunlik chuqur ish","short":"Bildirishnomalarsiz kundalik ish bloklari: 60 dan 180 daqiqagacha.","goal":"Bitta vazifaga diqqatni jamlashni va muhim ishlarni tushlikkacha yakunlashni oʻrganish.","rules":["Blok davomida telefon boshqa xonada turadi","Har blokka bitta vazifa, oldindan yozib qoʻyilgan","Belgi: blokda nima qilindi, 1–2 gap"],"phases":[{"title":"Tezlanish","tasks":["60 daqiqalik blok","60 daqiqalik blok + ertangi reja","75 daqiqalik blok"]},{"title":"Meʼyorlash","tasks":["90 daqiqalik blok","60 daqiqadan ikkita blok","90 daqiqalik blok, peshingacha pochtasiz"]},{"title":"Chuqurlik","tasks":["120 daqiqalik blok","150 daqiqalik blok","180 daqiqalik blok va retrospektiva"]}]},"en":{"title":"21 Days of Deep Work","short":"Daily notification-free work blocks: from 60 to 180 minutes.","goal":"Learn to hold focus on a single task and get important work done before lunch.","rules":["Phone stays in another room during the block","One task per block, written down in advance","Check-in: what you got done in the block, 1–2 sentences"],"phases":[{"title":"Ramp-up","tasks":["60-minute block","60-minute block + plan for tomorrow","75-minute block"]},{"title":"Settling in","tasks":["90-minute block","Two 60-minute blocks","90-minute block, no email before noon"]},{"title":"Depth","tasks":["120-minute block","150-minute block","180-minute block and a retro"]}]}}'::jsonb),
  ('mvp-14', 'MVP за 14 дней', 'business', 'hard', 14, 'rocket', '2026-10-17'::date, 'required', 149000, '{"ru":{"title":"MVP за 14 дней","short":"От идеи до первого платящего клиента за две недели.","goal":"Запустить минимальную версию продукта, получить 10 интервью и первую оплату.","rules":["Ежедневный отчет с артефактом: скрин, ссылка или таблица","Код и дизайн — любые инструменты, включая no-code","Демо-день на 14-й день"],"phases":[{"title":"Проблема","tasks":["Сформулируйте гипотезу в одном предложении","Найдите 20 потенциальных клиентов","Проведите 3 интервью","Проведите еще 4 интервью","Выпишите 3 главные боли"]},{"title":"Решение","tasks":["Лендинг с одной кнопкой","Прототип ключевого сценария","Покажите прототип 3 людям","Настройте прием оплаты"]},{"title":"Запуск","tasks":["Запустите рекламу на 1 000 ₽","Напишите 30 холодных писем","Соберите обратную связь","Подготовьте демо","Демо-день и итоги"]}]},"uz":{"title":"14 kunda MVP","short":"Ikki hafta ichida gʻoyadan birinchi toʻlovchi mijozgacha.","goal":"Mahsulotning minimal versiyasini ishga tushirish, 10 ta intervyu va birinchi toʻlovni olish.","rules":["Artefaktli kundalik hisobot: skrinshot, havola yoki jadval","Kod va dizayn — istalgan vositalar, jumladan no-code","14-kuni demo-kun"],"phases":[{"title":"Muammo","tasks":["Gipotezani bitta gapda ifodalang","20 ta potensial mijoz toping","3 ta intervyu oʻtkazing","Yana 4 ta intervyu oʻtkazing","3 ta asosiy muammoni yozib chiqing"]},{"title":"Yechim","tasks":["Bitta tugmali lending","Asosiy ssenariy prototipi","Prototipni 3 kishiga koʻrsating","Toʻlov qabul qilishni sozlang"]},{"title":"Ishga tushirish","tasks":["1 000 ₽ lik reklama yoqing","30 ta sovuq xat yozing","Fikr-mulohazalarni yigʻing","Demoni tayyorlang","Demo-kun va yakunlar"]}]},"en":{"title":"MVP in 14 Days","short":"From idea to your first paying customer in two weeks.","goal":"Launch a minimum version of the product, run 10 interviews and get your first payment.","rules":["Daily report with an artifact: a screenshot, link or spreadsheet","Code and design: any tools, no-code included","Demo day on day 14"],"phases":[{"title":"Problem","tasks":["State your hypothesis in one sentence","Find 20 potential customers","Run 3 interviews","Run 4 more interviews","Write down the top 3 pain points"]},{"title":"Solution","tasks":["A landing page with one button","Prototype the key user flow","Show the prototype to 3 people","Set up payments"]},{"title":"Launch","tasks":["Run ads with a 1,000 ₽ budget","Send 30 cold emails","Collect feedback","Prepare your demo","Demo day and wrap-up"]}]}}'::jsonb),
  ('read-20', '20 страниц в день', 'habits', 'easy', 30, 'book-open', null, 'none', 0, '{"ru":{"title":"20 страниц в день","short":"Минимум 20 страниц ежедневно. За месяц — две-три книги.","goal":"Вернуть привычку читать и закончить хотя бы две книги за месяц.","rules":["Засчитываются бумажные и электронные книги","Аудиокниги — 30 минут вместо 20 страниц","Чекин: одна мысль из прочитанного"],"phases":[{"title":"Старт","tasks":["Выберите книгу и прочтите 20 страниц","20 страниц + одна цитата","20 страниц перед сном без телефона"]}]},"uz":{"title":"Kuniga 20 sahifa","short":"Har kuni kamida 20 sahifa. Bir oyda — ikki-uchta kitob.","goal":"Kitob oʻqish odatini qaytarish va bir oyda kamida ikkita kitobni tugatish.","rules":["Qogʻoz va elektron kitoblar hisoblanadi","Audiokitob — 20 sahifa oʻrniga 30 daqiqa","Belgi: oʻqiganingizdan bitta fikr"],"phases":[{"title":"Start","tasks":["Kitob tanlang va 20 sahifa oʻqing","20 sahifa + bitta iqtibos","Uxlashdan oldin telefonsiz 20 sahifa"]}]},"en":{"title":"20 Pages a Day","short":"At least 20 pages every day. Two or three books a month.","goal":"Get back into the reading habit and finish at least two books in a month.","rules":["Paper books and e-books both count","Audiobooks: 30 minutes instead of 20 pages","Check-in: one idea from what you read"],"phases":[{"title":"Start","tasks":["Pick a book and read 20 pages","20 pages + one quote","20 pages before bed, no phone"]}]}}'::jsonb),
  ('calls-50', '50 звонков клиентам', 'business', 'medium', 10, 'phone', '2026-10-11'::date, 'optional', 0, '{"ru":{"title":"50 звонков клиентам","short":"Пять разговоров с клиентами каждый день в течение десяти дней.","goal":"Снять страх холодных звонков и собрать базу из 50 разговоров с выводами.","rules":["Звонок засчитывается от 3 минут разговора","После каждого звонка — заметка в CRM","Скрипт можно менять каждые 10 звонков"],"phases":[{"title":"Разогрев","tasks":["5 звонков текущим клиентам","5 звонков ушедшим клиентам","5 звонков по рекомендациям"]},{"title":"Холодные","tasks":["5 холодных звонков","5 холодных звонков и правка скрипта","5 звонков с предложением встречи"]},{"title":"Сделки","tasks":["5 повторных звонков","5 звонков с коммерческим предложением","5 звонков с закрытием","Итоги и таблица конверсии"]}]},"uz":{"title":"Mijozlarga 50 ta qoʻngʻiroq","short":"Oʻn kun davomida har kuni mijozlar bilan beshta suhbat.","goal":"Sovuq qoʻngʻiroqlar qoʻrquvini yengish va xulosalari bilan 50 ta suhbatdan iborat baza yigʻish.","rules":["Qoʻngʻiroq kamida 3 daqiqalik suhbat boʻlsa hisoblanadi","Har bir qoʻngʻiroqdan keyin — CRM da qayd","Skriptni har 10 ta qoʻngʻiroqda oʻzgartirish mumkin"],"phases":[{"title":"Qizish","tasks":["Joriy mijozlarga 5 ta qoʻngʻiroq","Ketgan mijozlarga 5 ta qoʻngʻiroq","Tavsiyalar boʻyicha 5 ta qoʻngʻiroq"]},{"title":"Sovuq qoʻngʻiroqlar","tasks":["5 ta sovuq qoʻngʻiroq","5 ta sovuq qoʻngʻiroq va skriptni tuzatish","Uchrashuv taklifi bilan 5 ta qoʻngʻiroq"]},{"title":"Bitimlar","tasks":["5 ta takroriy qoʻngʻiroq","Tijoriy taklif bilan 5 ta qoʻngʻiroq","Bitimni yopish uchun 5 ta qoʻngʻiroq","Yakunlar va konversiya jadvali"]}]},"en":{"title":"50 Client Calls","short":"Five conversations with clients every day for ten days.","goal":"Get over the fear of cold calling and build a log of 50 conversations with takeaways.","rules":["A call counts if the conversation lasts 3+ minutes","After every call, add a note in your CRM","You can change the script every 10 calls"],"phases":[{"title":"Warm-up","tasks":["5 calls to current clients","5 calls to former clients","5 calls to referrals"]},{"title":"Cold calls","tasks":["5 cold calls","5 cold calls and a script revision","5 calls proposing a meeting"]},{"title":"Deals","tasks":["5 follow-up calls","5 calls with a commercial offer","5 closing calls","Wrap-up and a conversion table"]}]}}'::jsonb),
  ('pushups-100', '100 отжиманий в день', 'sport', 'hard', 30, 'dumbbell', null, 'optional', 0, '{"ru":{"title":"100 отжиманий в день","short":"Сотня отжиманий ежедневно, разбивайте на подходы как удобно.","goal":"Выйти на 100 отжиманий в день и увеличить максимум в одном подходе вдвое.","rules":["Засчитываются только полные повторения","Подходы распределяйте в течение дня","Тест максимума в 1-й и 30-й день"],"phases":[{"title":"База","tasks":["Тест: максимум за один подход","60 отжиманий","70 отжиманий","Отдых: растяжка плеч"]},{"title":"Рост","tasks":["80 отжиманий","90 отжиманий","100 отжиманий"]},{"title":"Стабильность","tasks":["100 отжиманий","100 отжиманий, подходы по 20+"]}]},"uz":{"title":"Kuniga 100 ta otjimaniye","short":"Har kuni yuzta otjimaniye — yondashuvlarga qulay tarzda boʻling.","goal":"Kuniga 100 ta otjimaniyega chiqish va bitta yondashuvdagi maksimumni ikki barobar oshirish.","rules":["Faqat toʻliq takrorlar hisoblanadi","Yondashuvlarni kun davomida taqsimlang","Maksimum testi 1- va 30-kunlari"],"phases":[{"title":"Baza","tasks":["Test: bitta yondashuvdagi maksimum","60 ta otjimaniye","70 ta otjimaniye","Dam olish: yelkalarni choʻzish"]},{"title":"Oʻsish","tasks":["80 ta otjimaniye","90 ta otjimaniye","100 ta otjimaniye"]},{"title":"Barqarorlik","tasks":["100 ta otjimaniye","100 ta otjimaniye, har yondashuvda 20+"]}]},"en":{"title":"100 Push-ups a Day","short":"A hundred push-ups every day, split into sets however you like.","goal":"Work up to 100 push-ups a day and double your max in a single set.","rules":["Only full reps count","Spread your sets throughout the day","Max test on day 1 and day 30"],"phases":[{"title":"Base","tasks":["Test: max reps in one set","60 push-ups","70 push-ups","Rest: shoulder stretches"]},{"title":"Growth","tasks":["80 push-ups","90 push-ups","100 push-ups"]},{"title":"Consistency","tasks":["100 push-ups","100 push-ups in sets of 20+"]}]}}'::jsonb),
  ('no-sugar', '21 день без сахара', 'habits', 'medium', 21, 'candy-off', '2026-10-19'::date, 'none', 0, '{"ru":{"title":"21 день без сахара","short":"Без добавленного сахара, сладких напитков и десертов три недели.","goal":"Перезагрузить вкусовые привычки и стабилизировать энергию в течение дня.","rules":["Фрукты и ягоды разрешены","Читайте состав: сахар, сиропы, мальтодекстрин","Чекин: фото одного приема пищи"],"phases":[{"title":"Детокс","tasks":["Уберите сладкое из дома","День без сладких напитков","Найдите 3 замены десерту"]},{"title":"Привычка","tasks":["Изучите состав 5 привычных продуктов","Приготовьте завтрак без сахара","День без перекусов"]},{"title":"Закрепление","tasks":["Сходите в кафе и выберите без сахара","Запишите изменения в самочувствии"]}]},"uz":{"title":"21 kun shakarsiz","short":"Uch hafta qoʻshilgan shakar, shirin ichimliklar va desertlarsiz.","goal":"Taʼm odatlarini qayta sozlash va kun davomida energiyani barqarorlashtirish.","rules":["Mevalar va rezavorlar mumkin","Tarkibni oʻqing: shakar, siroplar, maltodekstrin","Belgi: bitta ovqatlanishning surati"],"phases":[{"title":"Detoks","tasks":["Uyingizdan shirinliklarni olib tashlang","Shirin ichimliklarsiz bir kun","Desertga 3 ta muqobil toping"]},{"title":"Odat","tasks":["Odatiy 5 ta mahsulot tarkibini oʻrganing","Shakarsiz nonushta tayyorlang","Gazaklarsiz bir kun"]},{"title":"Mustahkamlash","tasks":["Kafega borib, shakarsiz taom tanlang","Oʻzingizni his qilishdagi oʻzgarishlarni yozib qoʻying"]}]},"en":{"title":"21 Days Without Sugar","short":"Three weeks with no added sugar, sweet drinks or desserts.","goal":"Reset your taste habits and keep your energy steady throughout the day.","rules":["Fruit and berries are allowed","Read the labels: sugar, syrups, maltodextrin","Check-in: a photo of one meal"],"phases":[{"title":"Detox","tasks":["Clear the sweets out of your home","A day with no sweet drinks","Find 3 dessert substitutes"]},{"title":"Habit","tasks":["Check the ingredients of 5 foods you usually buy","Make a sugar-free breakfast","A day with no snacking"]},{"title":"Locking it in","tasks":["Go to a café and order something sugar-free","Write down how you feel different"]}]}}'::jsonb),
  ('english-15', '15 минут английского', 'growth', 'easy', 60, 'languages', '2026-10-10'::date, 'none', 49000, '{"ru":{"title":"15 минут английского","short":"Ежедневная микропрактика: слова, аудирование и короткие фразы вслух.","goal":"Выучить 600 слов в контексте и привыкнуть к ежедневной языковой практике.","rules":["15 минут в один заход","Чекин: 10 новых слов или фраза дня","Каждое воскресенье — повторение недели"],"phases":[{"title":"Ежедневно","tasks":["10 новых слов + примеры","Подкаст 10 минут + 5 слов","Скажите вслух 5 фраз о своем дне","Короткая статья и пересказ","Повторение недели"]}]},"uz":{"title":"15 daqiqa ingliz tili","short":"Kundalik mikromashq: soʻzlar, tinglab tushunish va qisqa iboralarni ovoz chiqarib aytish.","goal":"Kontekstda 600 ta soʻz oʻrganish va har kungi til amaliyotiga koʻnikish.","rules":["Bir oʻtirishda 15 daqiqa","Belgi: 10 ta yangi soʻz yoki kun iborasi","Har yakshanba — haftani takrorlash"],"phases":[{"title":"Har kuni","tasks":["10 ta yangi soʻz + misollar","10 daqiqa podkast + 5 ta soʻz","Kuningiz haqida 5 ta iborani ovoz chiqarib ayting","Qisqa maqola va uni qayta hikoya qilish","Haftani takrorlash"]}]},"en":{"title":"15 Minutes of English","short":"Daily micro-practice: vocabulary, listening and short phrases out loud.","goal":"Learn 600 words in context and get used to practising the language every day.","rules":["15 minutes in one sitting","Check-in: 10 new words or a phrase of the day","Every Sunday: review the week"],"phases":[{"title":"Daily","tasks":["10 new words + examples","10-minute podcast + 5 words","Say 5 phrases about your day out loud","A short article and a retelling","Review the week"]}]}}'::jsonb),
