  ('detox-7', 'Цифровой детокс', 'habits', 'easy', 7, 'smartphone', null, 'none', 0, '{"ru":{"title":"Цифровой детокс","short":"Неделя осознанного использования телефона: от 2 часов экранного времени.","goal":"Сократить экранное время до 2 часов в день и вернуть вечера себе.","rules":["Скриншот экранного времени ежедневно","После 21:00 — телефон не в спальне"],"phases":[{"title":"Неделя","tasks":["Удалите 3 самых затягивающих приложения","Отключите все уведомления, кроме звонков","Утро без телефона до 10:00","Вечер без экрана после 21:00","Прогулка без телефона","Экранное время меньше 2 часов","Итоги недели"]}]},"uz":{"title":"Raqamli detoks","short":"Telefondan ongli foydalanish haftasi: ekran vaqti 2 soatdan.","goal":"Ekran vaqtini kuniga 2 soatgacha qisqartirish va kechqurunlarni oʻzingizga qaytarish.","rules":["Har kuni ekran vaqti skrinshoti","21:00 dan keyin telefon yotoqxonada boʻlmaydi"],"phases":[{"title":"Hafta","tasks":["Eng koʻp vaqt oladigan 3 ta ilovani oʻchiring","Qoʻngʻiroqlardan tashqari barcha bildirishnomalarni oʻchiring","Soat 10:00 gacha telefonsiz tong","21:00 dan keyin ekransiz kechqurun","Telefonsiz sayr","Ekran vaqti 2 soatdan kam","Hafta yakunlari"]}]},"en":{"title":"Digital Detox","short":"A week of mindful phone use: from 2 hours of screen time.","goal":"Cut screen time to 2 hours a day and take your evenings back.","rules":["Daily screen time screenshot","After 21:00, no phone in the bedroom"],"phases":[{"title":"The week","tasks":["Delete your 3 most addictive apps","Turn off all notifications except calls","No phone in the morning until 10:00","No screens in the evening after 21:00","A walk without your phone","Screen time under 2 hours","Week wrap-up"]}]}}'::jsonb),
  ('plank-30', 'Планка: 30 дней', 'sport', 'medium', 30, 'timer', '2026-10-19'::date, 'required', 0, '{"ru":{"title":"Планка: 30 дней","short":"Каждый день короткая тренировка кора: от 3 × 20 секунд до 2 минут без остановки.","goal":"Укрепить мышцы кора и спины, научиться держать правильную технику и к финишу простоять в планке 2+ минуты.","rules":["Чекин — фото или видео с таймером во время планки","Спина прямая, таз не провисает; при боли в пояснице сразу остановитесь","Не держите время целиком — делите на подходы с отдыхом 30 секунд","Пропущенный день не догоняем двойной нагрузкой"],"phases":[{"title":"Основа","tasks":["Планка на предплечьях 3 × 20 секунд, отдых 30 секунд","Планка 3 × 25 секунд","Отдых: растяжка спины и бедер 10 минут","Планка 3 × 30 секунд","Боковая планка 2 × 15 секунд на каждую сторону","Планка 3 × 35 секунд","Отдых"]},{"title":"Выносливость","tasks":["Планка 2 × 45 секунд","Планка 2 × 50 секунд и боковая 2 × 20 секунд на сторону","Отдых: растяжка 10 минут","Планка 2 × 60 секунд","Планка на прямых руках 3 × 30 секунд","Планка 2 × 65 секунд","Отдых"]},{"title":"Усложнение","tasks":["Планка 75 секунд + 60 секунд","Планка с поочередным подъемом ног 3 × 30 секунд","Отдых","Планка 90 секунд и боковая 2 × 30 секунд на сторону","Планка с касанием плеч 3 × 20 касаний","Планка 100 секунд без остановки","Отдых: растяжка 10 минут","Планка 110 секунд без остановки"]},{"title":"Финиш","tasks":["Планка 2 минуты без остановки","Боковая планка 2 × 40 секунд на сторону","Отдых","Планка 2 минуты 15 секунд","Планка с подъемом ног 3 × 40 секунд","Отдых","Легкая разминка: планка 2 × 45 секунд","Финальный тест: максимум времени с правильной техникой"]}]},"uz":{"title":"Planka: 30 kun","short":"Har kuni korpus uchun qisqa mashgʻulot: 3 × 20 soniyadan 2 daqiqagacha toʻxtovsiz.","goal":"Korpus va bel mushaklarini mustahkamlash, toʻgʻri texnikani oʻrganish va marrada plankada 2+ daqiqa turish.","rules":["Belgi — planka paytida taymer koʻrinadigan foto yoki video","Bel tekis, chanoq osilmaydi; belda ogʻriq boʻlsa, darhol toʻxtang","Vaqtni bir martada ushlab turolmasangiz — 30 soniya dam bilan yondashuvlarga boʻling","Oʻtkazib yuborilgan kun ikki hissa yuklama bilan qoplanmaydi"],"phases":[{"title":"Asos","tasks":["Bilakda planka 3 × 20 soniya, dam 30 soniya","Planka 3 × 25 soniya","Dam olish: bel va son choʻzilishi 10 daqiqa","Planka 3 × 30 soniya","Yon planka har tomonga 2 × 15 soniya","Planka 3 × 35 soniya","Dam olish"]},{"title":"Chidamlilik","tasks":["Planka 2 × 45 soniya","Planka 2 × 50 soniya va yon planka har tomonga 2 × 20 soniya","Dam olish: choʻzilish 10 daqiqa","Planka 2 × 60 soniya","Toʻgʻri qoʻllarda planka 3 × 30 soniya","Planka 2 × 65 soniya","Dam olish"]},{"title":"Murakkablashtirish","tasks":["Planka 75 soniya + 60 soniya","Oyoqlarni navbat bilan koʻtarib planka 3 × 30 soniya","Dam olish","Planka 90 soniya va yon planka har tomonga 2 × 30 soniya","Yelkaga tegib planka 3 × 20 marta","Planka 100 soniya toʻxtovsiz","Dam olish: choʻzilish 10 daqiqa","Planka 110 soniya toʻxtovsiz"]},{"title":"Marra","tasks":["Planka 2 daqiqa toʻxtovsiz","Yon planka har tomonga 2 × 40 soniya","Dam olish","Planka 2 daqiqa 15 soniya","Oyoq koʻtarib planka 3 × 40 soniya","Dam olish","Yengil razminka: planka 2 × 45 soniya","Yakuniy test: toʻgʻri texnika bilan maksimal vaqt"]}]},"en":{"title":"Plank: 30 days","short":"A short core workout every day: from 3 × 20 seconds to 2 minutes non-stop.","goal":"Strengthen your core and back, learn proper form, and hold a plank for 2+ minutes by the finish.","rules":["Check-in: a photo or video with a timer visible during the plank","Keep your back straight and hips level; stop immediately if your lower back hurts","Can''t hold the full time? Split it into sets with 30 seconds of rest","Don''t make up a missed day with double volume"],"phases":[{"title":"Foundation","tasks":["Forearm plank 3 × 20 seconds, 30 seconds rest","Plank 3 × 25 seconds","Rest: 10 minutes of back and hip stretching","Plank 3 × 30 seconds","Side plank 2 × 15 seconds per side","Plank 3 × 35 seconds","Rest"]},{"title":"Endurance","tasks":["Plank 2 × 45 seconds","Plank 2 × 50 seconds and side plank 2 × 20 seconds per side","Rest: 10 minutes of stretching","Plank 2 × 60 seconds","Straight-arm plank 3 × 30 seconds","Plank 2 × 65 seconds","Rest"]},{"title":"Progression","tasks":["Plank 75 seconds + 60 seconds","Plank with alternating leg lifts 3 × 30 seconds","Rest","Plank 90 seconds and side plank 2 × 30 seconds per side","Plank shoulder taps 3 × 20 taps","Plank 100 seconds non-stop","Rest: 10 minutes of stretching","Plank 110 seconds non-stop"]},{"title":"Finish","tasks":["Plank 2 minutes non-stop","Side plank 2 × 40 seconds per side","Rest","Plank 2 minutes 15 seconds","Plank with leg lifts 3 × 40 seconds","Rest","Light warm-up: plank 2 × 45 seconds","Final test: your maximum time with proper form"]}]}}'::jsonb),
  ('yoga-21', '21 день йоги', 'sport', 'easy', 21, 'heart', null, 'optional', 0, '{"ru":{"title":"21 день йоги","short":"15–30 минут мягкой практики в день: гибкость, баланс и спокойное дыхание.","goal":"Сделать йогу ежедневной привычкой, снять зажимы в спине и бедрах и собрать собственную короткую практику.","rules":["Практикуйте натощак или через 2 часа после еды","Никакой боли: растяжение должно оставаться комфортным","Используйте коврик и при необходимости опору — подушку или блок","Отчет по желанию: фото или пара слов о самочувствии"],"phases":[{"title":"Знакомство","tasks":["15 минут: дыхание животом и поза ребенка","Кошка-корова и собака мордой вниз, 15 минут","Приветствие солнцу: 3 круга в медленном темпе","Мягкие скручивания сидя и лежа, 15 минут","Позы воина I и II по 30 секунд на сторону","Растяжка задней поверхности бедра, 15 минут","Отдых или 10 минут дыхания и шавасаны"]},{"title":"Баланс","tasks":["Приветствие солнцу: 5 кругов","Поза дерева и воина III по 30 секунд на сторону","Раскрытие тазобедренных и поза голубя, 20 минут","Мостик 3 × 30 секунд и мягкие прогибы","Комплекс для спины после рабочего дня, 20 минут","Позы треугольника и бокового угла","Отдых или йога-нидра 15 минут"]},{"title":"Поток","tasks":["Приветствие солнцу: 7 кругов","Связка воинов в потоке, 20 минут","Балансы: дерево, орел, воин III","Комплекс для бедер и спины, 25 минут","Утренняя практика 20 минут до завтрака","Соберите свою последовательность из любимых поз","Финальная практика 30 минут и запись ощущений"]}]},"uz":{"title":"21 kunlik yoga","short":"Kuniga 15–30 daqiqa yumshoq amaliyot: egiluvchanlik, muvozanat va xotirjam nafas.","goal":"Yogani kundalik odatga aylantirish, bel va sondagi qotishlarni boʻshatish va oʻzingizning qisqa amaliyotingizni tuzish.","rules":["Och qoringa yoki ovqatdan 2 soat keyin shugʻullaning","Ogʻriq boʻlmasin: choʻzilish qulay boʻlib qolishi kerak","Gilamcha va kerak boʻlsa tayanch — yostiq yoki blokdan foydalaning","Hisobot ixtiyoriy: foto yoki holatingiz haqida bir-ikki soʻz"],"phases":[{"title":"Tanishuv","tasks":["15 daqiqa: qorin bilan nafas va bola pozasi","Mushuk-sigir va pastga qaragan it, 15 daqiqa","Quyoshga salom: sekin surʼatda 3 aylana","Oʻtirib va yotib yumshoq burilishlar, 15 daqiqa","Jangchi I va II pozalari, har tomonga 30 soniya","Son orqa yuzasini choʻzish, 15 daqiqa","Dam olish yoki 10 daqiqa nafas va shavasana"]},{"title":"Muvozanat","tasks":["Quyoshga salom: 5 aylana","Daraxt va jangchi III pozalari, har tomonga 30 soniya","Chanoq-son boʻgʻimlarini ochish va kaptar pozasi, 20 daqiqa","Koʻprik 3 × 30 soniya va yumshoq egilishlar","Ish kunidan keyin bel uchun majmua, 20 daqiqa","Uchburchak va yon burchak pozalari","Dam olish yoki yoga-nidra 15 daqiqa"]},{"title":"Oqim","tasks":["Quyoshga salom: 7 aylana","Jangchilar ketma-ketligi oqimda, 20 daqiqa","Muvozanatlar: daraxt, burgut, jangchi III","Son va bel uchun majmua, 25 daqiqa","Nonushtadan oldin 20 daqiqalik ertalabki amaliyot","Sevimli pozalaringizdan oʻz ketma-ketligingizni tuzing","Yakuniy 30 daqiqalik amaliyot va his-tuygʻularni yozib qoʻyish"]}]},"en":{"title":"21 days of yoga","short":"15–30 minutes of gentle practice a day: flexibility, balance and calm breathing.","goal":"Make yoga a daily habit, release tension in your back and hips, and build a short practice of your own.","rules":["Practice on an empty stomach or 2 hours after a meal","No pain: every stretch should stay comfortable","Use a mat and, if needed, a prop such as a cushion or block","Report is optional: a photo or a few words on how you feel"],"phases":[{"title":"Getting started","tasks":["15 minutes: belly breathing and child''s pose","Cat-cow and downward dog, 15 minutes","Sun salutation: 3 slow rounds","Gentle seated and lying twists, 15 minutes","Warrior I and II, 30 seconds per side","Hamstring stretching, 15 minutes","Rest or 10 minutes of breathing and savasana"]},{"title":"Balance","tasks":["Sun salutation: 5 rounds","Tree and warrior III, 30 seconds per side","Hip openers and pigeon pose, 20 minutes","Bridge 3 × 30 seconds and gentle backbends","After-work back routine, 20 minutes","Triangle and side angle poses","Rest or 15 minutes of yoga nidra"]},{"title":"Flow","tasks":["Sun salutation: 7 rounds","Warrior flow sequence, 20 minutes","Balances: tree, eagle, warrior III","Hips and back routine, 25 minutes","20-minute morning practice before breakfast","Build your own sequence from your favorite poses","Final 30-minute practice and notes on how you feel"]}]}}'::jsonb),
  ('sales-sprint', 'Спринт продаж: 14 дней', 'business', 'hard', 14, 'target', '2026-11-02'::date, 'required', 99000, '{"ru":{"title":"Спринт продаж: 14 дней","short":"Две недели системных продаж: своя воронка, 20+ касаний в день и разбор каждого отказа.","goal":"Выстроить ежедневный ритм продаж и закрыть первые сделки: 250+ касаний, 10+ встреч и понятная конверсия на каждом этапе воронки.","rules":["Чекин — скриншот CRM или таблицы с касаниями за день","Минимум 20 касаний в день: звонки, сообщения, письма","Каждый вечер — 10 минут разбора: что сработало, а что нет","Без спама: только релевантные контакты и честные предложения"],"phases":[{"title":"Подготовка","tasks":["Опишите идеального клиента и 3 его главные боли","Соберите базу из 100 контактов в таблицу или CRM","Напишите скрипт первого касания и ответы на 5 возражений","20 касаний по теплой базе: бывшие клиенты и знакомые"]},{"title":"Ритм","tasks":["20 холодных касаний и фиксация всех ответов","Назначьте 2 встречи или созвона","20 касаний и follow-up всем, кто не ответил 3 дня назад","Проведите встречи по схеме: вопросы → боль → решение","Посчитайте конверсию каждого этапа воронки"]},{"title":"Закрытие","tasks":["Перепишите самое слабое место скрипта по итогам цифр","25 касаний и 3 коммерческих предложения","Попросите 2 рекомендации у довольных клиентов","Дожмите горячие сделки: звонок с конкретным следующим шагом","Итоги спринта: цифры, выручка и план продаж на месяц"]}]},"uz":{"title":"Savdo sprinti: 14 kun","short":"Ikki hafta tizimli savdo: oʻz voronkangiz, kuniga 20+ aloqa va har bir rad javobini tahlil qilish.","goal":"Kundalik savdo ritmini yoʻlga qoʻyish va ilk bitimlarni yopish: 250+ aloqa, 10+ uchrashuv va voronkaning har bir bosqichida aniq konversiya.","rules":["Belgi — kunlik aloqalar koʻrsatilgan CRM yoki jadval skrinshoti","Kuniga kamida 20 ta aloqa: qoʻngʻiroqlar, xabarlar, xatlar","Har oqshom 10 daqiqa tahlil: nima ishladi, nima ishlamadi","Spamsiz: faqat mos kontaktlar va halol takliflar"],"phases":[{"title":"Tayyorgarlik","tasks":["Ideal mijozni va uning 3 asosiy muammosini yozib chiqing","Jadval yoki CRMda 100 ta kontaktdan iborat baza yigʻing","Birinchi aloqa skriptini va 5 ta eʼtirozga javoblarni yozing","Iliq baza boʻyicha 20 ta aloqa: sobiq mijozlar va tanishlar"]},{"title":"Ritm","tasks":["20 ta sovuq aloqa va barcha javoblarni qayd etish","2 ta uchrashuv yoki qoʻngʻiroq belgilang","20 ta aloqa va 3 kun oldin javob bermaganlarga follow-up","Uchrashuvlarni sxema boʻyicha oʻtkazing: savollar → muammo → yechim","Voronkaning har bir bosqichi konversiyasini hisoblang"]},{"title":"Yopish","tasks":["Raqamlar natijasiga koʻra skriptning eng zaif joyini qayta yozing","25 ta aloqa va 3 ta tijorat taklifi","Mamnun mijozlardan 2 ta tavsiya soʻrang","Issiq bitimlarni yakunlang: aniq keyingi qadam bilan qoʻngʻiroq","Sprint yakuni: raqamlar, tushum va bir oylik savdo rejasi"]}]},"en":{"title":"Sales sprint: 14 days","short":"Two weeks of systematic selling: your own funnel, 20+ touches a day and a review of every rejection.","goal":"Build a daily sales rhythm and close your first deals: 250+ touches, 10+ meetings and a clear conversion rate at every funnel stage.","rules":["Check-in: a screenshot of your CRM or spreadsheet with the day''s touches","At least 20 touches a day: calls, messages, emails","Every evening, a 10-minute review of what worked and what didn''t","No spam: only relevant contacts and honest offers"],"phases":[{"title":"Preparation","tasks":["Describe your ideal customer and their 3 biggest pains","Build a list of 100 contacts in a spreadsheet or CRM","Write a first-touch script and answers to 5 objections","20 touches to your warm list: past clients and acquaintances"]},{"title":"Rhythm","tasks":["20 cold touches, logging every reply","Book 2 meetings or calls","20 touches plus a follow-up to everyone who didn''t reply 3 days ago","Run meetings using the flow: questions → pain → solution","Calculate the conversion rate at each funnel stage"]},{"title":"Closing","tasks":["Rewrite the weakest part of your script based on the numbers","25 touches and 3 proposals","Ask happy clients for 2 referrals","Push hot deals forward: a call with a concrete next step","Sprint wrap-up: numbers, revenue and a sales plan for the month"]}]}}'::jsonb),
  ('networking-21', 'Нетворкинг: 21 день', 'business', 'medium', 21, 'users', '2026-10-26'::date, 'optional', 0, '{"ru":{"title":"Нетворкинг: 21 день","short":"Каждый день одно полезное касание: новое знакомство, помощь или восстановленный контакт.","goal":"Расширить профессиональную сеть на 20+ человек и превратить знакомства в регулярный обмен пользой.","rules":["Одно осознанное касание в день — не массовая рассылка","Сначала дайте пользу, потом просите","Ведите список: кто, где познакомились, о чем договорились","Отчет по желанию: с кем и о чем поговорили"],"phases":[{"title":"Ревизия","tasks":["Выпишите 20 человек, с которыми давно не общались, и напишите одному","Обновите профиль в LinkedIn или Telegram: кто вы и чем полезны","Поблагодарите коллегу за конкретный результат"]},{"title":"Новые связи","tasks":["Познакомьтесь с одним человеком из своей отрасли","Оставьте содержательный комментарий эксперту, за которым следите","Попросите знакомого представить вас нужному человеку"]},{"title":"Польза","tasks":["Познакомьте двух людей, которым полезно знать друг друга","Поделитесь вакансией, контактом или статьей с тем, кому это нужно","Пригласите кого-то на кофе или 20-минутный созвон"]}]},"uz":{"title":"Netvorking: 21 kun","short":"Har kuni bitta foydali aloqa: yangi tanishuv, yordam yoki tiklangan kontakt.","goal":"Professional tarmoqni 20+ kishiga kengaytirish va tanishuvlarni muntazam foyda almashinuviga aylantirish.","rules":["Kuniga bitta ongli aloqa — ommaviy xabar tarqatish emas","Avval foyda bering, keyin soʻrang","Roʻyxat yuriting: kim, qayerda tanishdingiz, nima haqida kelishdingiz","Hisobot ixtiyoriy: kim bilan va nima haqida gaplashdingiz"],"phases":[{"title":"Qayta koʻrib chiqish","tasks":["Uzoq vaqt gaplashmagan 20 kishini yozib chiqing va biriga xabar yozing","LinkedIn yoki Telegramdagi profilingizni yangilang: kimsiz va qanday foydalisiz","Hamkasbingizga aniq natijasi uchun minnatdorchilik bildiring"]},{"title":"Yangi aloqalar","tasks":["Oʻz sohangizdan bir kishi bilan tanishing","Kuzatib boradigan ekspertingizga mazmunli izoh qoldiring","Tanishingizdan sizni kerakli odamga tanishtirishni soʻrang"]},{"title":"Foyda","tasks":["Bir-birini bilishi foydali boʻlgan ikki kishini tanishtiring","Vakansiya, kontakt yoki maqolani kerakli odam bilan baham koʻring","Kimnidir qahvaga yoki 20 daqiqalik qoʻngʻiroqqa taklif qiling"]}]},"en":{"title":"Networking: 21 days","short":"One useful touch every day: a new connection, a favor or a revived contact.","goal":"Grow your professional network by 20+ people and turn new connections into a regular exchange of value.","rules":["One intentional touch a day, not a mass mailing","Give value first, then ask","Keep a list: who, where you met, what you agreed on","Report is optional: who you talked to and what about"],"phases":[{"title":"Audit","tasks":["List 20 people you haven''t talked to in a while and message one of them","Update your LinkedIn or Telegram profile: who you are and how you help","Thank a colleague for a specific result"]},{"title":"New connections","tasks":["Meet one new person from your industry","Leave a thoughtful comment for an expert you follow","Ask an acquaintance to introduce you to someone you need"]},{"title":"Giving value","tasks":["Introduce two people who would benefit from knowing each other","Share a job opening, contact or article with someone who needs it","Invite someone for coffee or a 20-minute call"]}]}}'::jsonb),
  ('water-2l', '2 литра воды: 14 дней', 'habits', 'easy', 14, 'droplets', null, 'none', 0, '{"ru":{"title":"2 литра воды: 14 дней","short":"Пейте достаточно воды каждый день и замечайте, как меняются энергия и концентрация.","goal":"Закрепить привычку пить около 2 литров воды в день без усилий и напоминаний.","rules":["Норма — около 2 литров, включая несладкий чай; ориентируйтесь на самочувствие","При заболеваниях сердца или почек согласуйте объем с врачом","Сладкие напитки и кофе в норму не входят","Чекин вечером: сколько выпито за день"],"phases":[{"title":"Старт","tasks":["Стакан воды сразу после пробуждения","Поставьте бутылку воды на рабочий стол и выпейте ее до обеда","Стакан воды перед каждым приемом пищи"]},{"title":"Привычка","tasks":["Замените один сладкий напиток водой","Выпейте 2 литра равномерно, без больших объемов за раз","Отметьте, как изменились энергия и чувство голода","2 литра без напоминаний — проверьте, держится ли привычка"]}]},"uz":{"title":"2 litr suv: 14 kun","short":"Har kuni yetarlicha suv iching va quvvat hamda diqqat qanday oʻzgarishini kuzating.","goal":"Kuniga taxminan 2 litr suv ichish odatini zoʻriqishsiz va eslatmalarsiz mustahkamlash.","rules":["Meʼyor — taxminan 2 litr, shakarsiz choy bilan birga; holatingizga qarab moʻljal oling","Yurak yoki buyrak kasalliklarida hajmni shifokor bilan kelishing","Shirin ichimliklar va qahva meʼyorga kirmaydi","Belgi kechqurun: kun davomida qancha ichildi"],"phases":[{"title":"Start","tasks":["Uygʻongan zahoti bir stakan suv","Ish stolingizga bir shisha suv qoʻying va tushlikkacha iching","Har bir ovqatdan oldin bir stakan suv"]},{"title":"Odat","tasks":["Bitta shirin ichimlikni suvga almashtiring","2 litrni bir tekisda iching, bir martada koʻp ichmang","Quvvat va ochlik hissi qanday oʻzgarganini yozib qoʻying","Eslatmalarsiz 2 litr — odat saqlanayotganini tekshiring"]}]},"en":{"title":"2 liters of water: 14 days","short":"Drink enough water every day and notice how your energy and focus change.","goal":"Lock in the habit of drinking about 2 liters of water a day without effort or reminders.","rules":["The target is about 2 liters, unsweetened tea included; listen to your body","If you have heart or kidney conditions, agree on the amount with your doctor","Sugary drinks and coffee don''t count","Evening check-in: how much you drank today"],"phases":[{"title":"Start","tasks":["A glass of water right after waking up","Put a bottle of water on your desk and finish it before lunch","A glass of water before every meal"]},{"title":"Habit","tasks":["Replace one sugary drink with water","Drink 2 liters evenly, without large amounts at once","Note how your energy and hunger have changed","2 liters with no reminders: check that the habit holds"]}]}}'::jsonb),
  ('sleep-23', 'Отбой в 23:00', 'habits', 'medium', 28, 'moon', '2026-11-16'::date, 'none', 0, '{"ru":{"title":"Отбой в 23:00","short":"Четыре недели ложимся до 23:00 и встаем в одно время — даже в выходные.","goal":"Наладить стабильный режим сна 7–8 часов и просыпаться бодрым без пяти будильников.","rules":["Чекин утром: во сколько легли и встали","Подъем в одно время ±30 минут, включая выходные","Экраны — не позже чем за 30 минут до сна","Кофеин — не позже 14:00"],"phases":[{"title":"Сдвиг","tasks":["Лягте на 15 минут раньше обычного","Выберите фиксированное время подъема и поставьте один будильник","Уберите телефон из кровати: зарядка в другом конце комнаты"]},{"title":"Ритуал","tasks":["Вечерний ритуал 20 минут: душ, чтение, приглушенный свет","Отбой в 23:30","Проветрите спальню перед сном"]},{"title":"Режим","tasks":["Отбой в 23:00","Последний прием пищи за 3 часа до сна","Перед сном выпишите тревожные мысли на бумагу"]},{"title":"Закрепление","tasks":["Отбой в 23:00 без исключений","Утром 10 минут дневного света","Оцените сон по шкале 1–10 и сравните с первой неделей"]}]},"uz":{"title":"23:00 da uyqu","short":"Toʻrt hafta 23:00 gacha yotamiz va bir vaqtda turamiz — dam olish kunlari ham.","goal":"7–8 soatlik barqaror uyqu tartibini yoʻlga qoʻyish va beshta budilniksiz tetik uygʻonish.","rules":["Belgi ertalab: soat nechada yotdingiz va turdingiz","Dam olish kunlari ham bir vaqtda ±30 daqiqa turish","Ekranlar — uyqudan kamida 30 daqiqa oldin oʻchiriladi","Kofein — soat 14:00 dan kechiktirmay"],"phases":[{"title":"Siljish","tasks":["Odatdagidan 15 daqiqa erta yoting","Doimiy turish vaqtini tanlang va bitta budilnik qoʻying","Telefonni karavotdan olib qoʻying: quvvatlagich xonaning narigi chetida"]},{"title":"Marosim","tasks":["20 daqiqalik kechki marosim: dush, kitob, xira yorugʻlik","23:30 da uyqu","Uxlashdan oldin yotoqxonani shamollating"]},{"title":"Tartib","tasks":["23:00 da uyqu","Oxirgi ovqat uyqudan 3 soat oldin","Uxlashdan oldin bezovta qilayotgan fikrlarni qogʻozga yozing"]},{"title":"Mustahkamlash","tasks":["Istisnosiz 23:00 da uyqu","Ertalab 10 daqiqa kunduzgi yorugʻlik","Uyquni 1–10 shkalada baholang va birinchi hafta bilan solishtiring"]}]},"en":{"title":"Lights out at 11 pm","short":"Four weeks of going to bed by 11 pm and getting up at the same time, weekends included.","goal":"Settle into a steady 7–8 hour sleep schedule and wake up refreshed without five alarms.","rules":["Morning check-in: when you went to bed and got up","Wake up at the same time ±30 minutes, weekends included","Screens off at least 30 minutes before bed","No caffeine after 2 pm"],"phases":[{"title":"Shift","tasks":["Go to bed 15 minutes earlier than usual","Pick a fixed wake-up time and set just one alarm","Get your phone out of bed: charge it across the room"]},{"title":"Ritual","tasks":["A 20-minute evening ritual: shower, reading, dim lights","Lights out at 11:30 pm","Air out the bedroom before bed"]},{"title":"Routine","tasks":["Lights out at 11 pm","Last meal 3 hours before bed","Write down anxious thoughts on paper before bed"]},{"title":"Lock-in","tasks":["Lights out at 11 pm, no exceptions","10 minutes of daylight in the morning","Rate your sleep from 1 to 10 and compare it with week one"]}]}}'::jsonb),
  ('code-60', '60 дней кода', 'growth', 'hard', 60, 'code', null, 'none', 39000, '{"ru":{"title":"60 дней кода","short":"Одна задача по программированию каждый день: от алгоритмов до собственного проекта.","goal":"Решить 60 задач, уверенно владеть базовыми структурами данных и собрать свой pet-проект с тестами.","rules":["Минимум 45 минут кода в день, язык — любой","Каждое решение сохраняйте в свой репозиторий","Подсмотрели решение — на следующий день напишите его сами с нуля","Чекин: пара строк о том, что решили и чему научились"],"phases":[{"title":"Основы","tasks":["Задача на строки: разворот, палиндромы, подсчет символов","Задача на массивы: поиск, сортировка, два указателя","Задача на хеш-таблицы: частоты и дубликаты","Разбор: перепишите вчерашнее решение чище и короче"]},{"title":"Структуры","tasks":["Задача на стек или очередь","Задача на рекурсию","Задача на деревья: обход в глубину и в ширину","Задача на бинарный поиск"]},{"title":"Проект","tasks":["Спланируйте pet-проект: опишите 5 функций в README","Реализуйте одну функцию проекта","Напишите тесты к вчерашнему коду","Рефакторинг и коммит с понятным описанием"]}]},"uz":{"title":"60 kunlik kod","short":"Har kuni bitta dasturlash masalasi: algoritmlardan oʻz loyihangizgacha.","goal":"60 ta masala yechish, asosiy maʼlumotlar tuzilmalarini ishonchli egallash va testlari bor oʻz pet-loyihangizni yaratish.","rules":["Kuniga kamida 45 daqiqa kod, til — istalgan","Har bir yechimni oʻz repozitoriyingizga saqlang","Yechimni koʻrib oldingizmi — ertasi kuni uni noldan oʻzingiz yozing","Belgi: nimani yechganingiz va nimani oʻrganganingiz haqida bir-ikki qator"],"phases":[{"title":"Asoslar","tasks":["Satrlar boʻyicha masala: teskari aylantirish, palindromlar, belgilarni sanash","Massivlar boʻyicha masala: qidiruv, saralash, ikki koʻrsatkich","Xesh-jadvallar boʻyicha masala: chastotalar va dublikatlar","Tahlil: kechagi yechimni toza va qisqaroq qilib qayta yozing"]},{"title":"Tuzilmalar","tasks":["Stek yoki navbat boʻyicha masala","Rekursiya boʻyicha masala","Daraxtlar boʻyicha masala: chuqurlik va kenglik boʻyicha aylanib chiqish","Ikkilik qidiruv boʻyicha masala"]},{"title":"Loyiha","tasks":["Pet-loyihani rejalashtiring: READMEda 5 ta funksiyani tasvirlang","Loyihaning bitta funksiyasini amalga oshiring","Kechagi kodga testlar yozing","Refaktoring va tushunarli tavsifli kommit"]}]},"en":{"title":"60 days of code","short":"One programming task every day: from algorithms to a project of your own.","goal":"Solve 60 problems, get confident with core data structures and build your own pet project with tests.","rules":["At least 45 minutes of coding a day, any language","Save every solution to your own repository","Peeked at a solution? Write it yourself from scratch the next day","Check-in: a couple of lines on what you solved and what you learned"],"phases":[{"title":"Basics","tasks":["String problem: reversal, palindromes, character counts","Array problem: search, sorting, two pointers","Hash table problem: frequencies and duplicates","Review: rewrite yesterday''s solution cleaner and shorter"]},{"title":"Structures","tasks":["Stack or queue problem","Recursion problem","Tree problem: depth-first and breadth-first traversal","Binary search problem"]},{"title":"Project","tasks":["Plan a pet project: describe 5 features in the README","Implement one feature of the project","Write tests for yesterday''s code","Refactor and commit with a clear message"]}]}}'::jsonb),
  ('pomodoro-7', 'Помодоро: неделя фокуса', 'growth', 'easy', 7, 'focus', null, 'none', 0, '{"ru":{"title":"Помодоро: неделя фокуса","short":"7 дней работы по технике помидора: 25 минут фокуса, 5 минут отдыха.","goal":"Научиться работать без отвлечений и к концу недели выдавать 8 полноценных помидоров в день.","rules":["Помидор — 25 минут над одной задачей без уведомлений и соцсетей","После 4 помидоров — длинный перерыв 15–30 минут","Прервались — помидор не засчитывается, начните заново","Чекин вечером: сколько помидоров сделано"],"phases":[{"title":"Настройка","tasks":["4 помидора и список задач с утра","5 помидоров с отключенными уведомлениями","6 помидоров, записывайте каждое отвлечение на бумагу"]},{"title":"Ритм","tasks":["6 помидоров, самая сложная задача — первой","7 помидоров, перерывы без телефона","8 помидоров в двух блоках по 4","8 помидоров и итоги недели: что мешало и что помогло"]}]},"uz":{"title":"Pomodoro: diqqat haftasi","short":"Pomidor usulida 7 kun ishlash: 25 daqiqa diqqat, 5 daqiqa dam.","goal":"Chalgʻimasdan ishlashni oʻrganish va hafta oxiriga kelib kuniga 8 ta toʻliq pomidor bajarish.","rules":["Pomidor — bildirishnomalar va ijtimoiy tarmoqlarsiz bitta vazifa ustida 25 daqiqa","4 ta pomidordan keyin 15–30 daqiqalik uzun tanaffus","Chalgʻidingizmi — pomidor hisoblanmaydi, qaytadan boshlang","Belgi kechqurun: nechta pomidor bajarildi"],"phases":[{"title":"Sozlash","tasks":["4 ta pomidor va ertalabdan vazifalar roʻyxati","Bildirishnomalar oʻchirilgan holda 5 ta pomidor","6 ta pomidor, har bir chalgʻishni qogʻozga yozing"]},{"title":"Ritm","tasks":["6 ta pomidor, eng qiyin vazifa — birinchi","7 ta pomidor, tanaffuslar telefonsiz","4 tadan ikki blokda 8 ta pomidor","8 ta pomidor va hafta yakuni: nima xalaqit berdi, nima yordam berdi"]}]},"en":{"title":"Pomodoro: a week of focus","short":"7 days with the Pomodoro technique: 25 minutes of focus, 5 minutes of rest.","goal":"Learn to work without distractions and reach 8 full pomodoros a day by the end of the week.","rules":["A pomodoro is 25 minutes on one task with no notifications or social media","After 4 pomodoros, take a long 15–30 minute break","Interrupted? That pomodoro doesn''t count, start over","Evening check-in: how many pomodoros you completed"],"phases":[{"title":"Setup","tasks":["4 pomodoros and a task list first thing in the morning","5 pomodoros with notifications turned off","6 pomodoros, writing every distraction down on paper"]},{"title":"Rhythm","tasks":["6 pomodoros, hardest task first","7 pomodoros, breaks without your phone","8 pomodoros in two blocks of 4","8 pomodoros and a weekly review: what got in the way and what helped"]}]}}'::jsonb)
